bool PP_ImageData_Init(PP_ImageDataFormat format, int width, int height, bool init_to_zero) {
    // Check if the image format is supported
    if (format < 0 || format >= PP_IMAGEDATAFORMAT_COUNT)
        return false;

    // Validate width and height
    if (width <= 0 || height <= 0)
        return false;

    // Set member variables (example - adjust according to actual struct)
    imageData.format = format;
    imageData.width = width;
    imageData.height = height;
    imageData.init_to_zero = init_to_zero;

    // Allocate data buffer if needed
    if (init_to_zero) {
        imageData.data = (uint8_t *)malloc(width * height * GetBytesPerPixel(format));
        if (!imageData.data) {
            return false; // Allocation failed
        }
        memset(imageData.data, 0, width * height * GetBytesPerPixel(format));
    }

    // Call backend initialization
    if (!Backend_Init(&imageData)) {
        if (imageData.data) {
